const wd="/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild";
const cmds=[
"sed -n '1,330p' AlgebraicJacobian/Picard/DivisorFamilyZar.lean",
"sed -n '1,130p' AlgebraicJacobian/Picard/DivisorFamilyZarFunctor.lean",
"sed -n '50,130p' AlgebraicJacobian/Picard/DivRepKit.lean",
"rg -n \"IsLocallyCertified|DivFamZar\" AlgebraicJacobian/Picard/DivisorFamilyZar*.lean | head -n 260"
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:wd,yield_time_ms:10000,max_output_tokens:30000})));
rs.forEach((r,i)=>text(`===${i+1}===\n${r.output}`));

