"$HORIZON_GIT diff --check -- MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian.lean MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/Curve/P1Aut.lean MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/Picard/DivSchemeCertZarFibreAvoid.lean",
"$HORIZON_GIT diff --stat -- MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian.lean MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/Curve/P1Aut.lean MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/Picard/DivSchemeCertZarFibreAvoid.lean"
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:wd,yield_time_ms:10000,max_output_tokens:10000})));
